export interface Sched {
  now(): number;
}
export interface Observer<T> {
  next: (value: T) => void;
  complete: () => void;
}
export class Stream<T> {
  private readonly produce: (o: Observer<T>) => void;
  constructor(produce: (o: Observer<T>) => void) {
    this.produce = produce;
  }
  subscribe(o?: Partial<Observer<T>> | ((value: T) => void)): void {
    const full: Observer<T> =
      typeof o === "function"
        ? { next: o, complete: () => {} }
        : { next: (v) => o?.next?.(v), complete: () => o?.complete?.() };
    this.produce(full);
  }
}

function isSched(value: any): value is Sched {
  return !!value && typeof value.now === "function";
}

export function of<T>(value: T, scheduler: Sched): Stream<T>;
export function of<A extends readonly unknown[]>(...valuesAndScheduler: [...A, Sched]): Stream<A[number]>;
export function of(): Stream<never>;
export function of<T>(value: T): Stream<T>;
export function of<A extends readonly unknown[]>(...values: A): Stream<A[number]>;
export function of<T>(...args: Array<T | Sched>): Stream<T> {
  const items = (isSched(args[args.length - 1]) ? args.slice(0, -1) : args) as T[];
  return new Stream<T>((o) => {
    for (const v of items) o.next(v);
    o.complete();
  });
}

export type StreamFactory<R> = () => Stream<R> | PromiseLike<R> | R[];

export function defer<R>(factory: StreamFactory<R>): Stream<R> {
  return new Stream<R>((o) => {
    const made = factory();
    if (made instanceof Stream) made.subscribe(o);
    else if (Array.isArray(made)) {
      for (const v of made) o.next(v);
      o.complete();
    } else {
      made.then((v) => {
        o.next(v);
        o.complete();
      });
    }
  });
}

export function lastValueFrom<T>(source: Stream<T>): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    let has = false;
    let value: T;
    source.subscribe({
      next: (v) => {
        has = true;
        value = v;
      },
      complete: () => (has ? resolve(value) : reject(new Error("no elements"))),
    });
  });
}
